pipeline {
  agent { label 'linux' }
  stages {
    stage('PR checks') {
      when { changeRequest() }
      steps {
        withCredentials([string(credentialsId: 'npm-publish-token', variable: 'NPM_TOKEN')]) {
          sh 'npm ci && npm test'
        }
      }
    }
  }
}

pipeline {
  agent { label 'linux' }
  stages {
    stage('Announce') {
      when { changeRequest() }
      steps {
        sh "echo Building PR: ${env.CHANGE_TITLE} by ${env.CHANGE_AUTHOR}"
      }
    }
    stage('Build') {
      steps { sh './gradlew build' }
    }
  }
}

pipeline {
  agent { label 'linux' }
  stages {
    stage('Invalidate CDN') {
      when { branch 'main' }
      steps {
        withAWS(role: 'arn:aws:iam::123456789012:role/ci-full-admin', region: 'us-east-1') {
          sh 'aws cloudfront create-invalidation --distribution-id E1EXAMPLE --paths "/*"'
        }
      }
    }
  }
}

pipeline {
  agent { label 'linux' }
  stages {
    stage('Smoke check') {
      steps {
        withKubeConfig([credentialsId: 'k8s-cluster-admin-token', serverUrl: 'https://k8s.example.com']) {
          sh 'kubectl -n qa get pods'
          sh 'kubectl -n qa rollout status deploy/api --timeout=120s'
        }
      }
    }
  }
}

pipeline {
  agent {
    docker { image 'maven:3.9-eclipse-temurin-21' }
  }
  stages {
    stage('Build') {
      steps { sh 'mvn -B -ntp verify' }
    }
    stage('Archive') {
      steps { archiveArtifacts artifacts: 'target/*.jar', fingerprint: true }
    }
  }
}

pipeline {
  agent { label 'linux' }
  stages {
    stage('Codegen') {
      steps {
        sh 'go install github.com/example/protoc-gen-api@latest'
        sh 'buf generate'
      }
    }
    stage('Test') {
      steps { sh 'go test ./...' }
    }
  }
}

pipeline {
  agent { label 'linux' }
  environment {
    SONAR_TOKEN = 'sqp_FAKE1234567890abcdefFAKE1234567890ab'
  }
  stages {
    stage('Analyze') {
      steps {
        sh './gradlew sonar -Dsonar.host.url=https://sonar.example.com'
      }
    }
  }
}

pipeline {
  agent { label 'linux' }
  stages {
    stage('Publish') {
      when { branch 'main' }
      steps {
        withCredentials([usernamePassword(credentialsId: 'nexus-deploy', usernameVariable: 'NEXUS_USER', passwordVariable: 'NEXUS_PASS')]) {
          sh 'echo "Publishing as $NEXUS_USER with password $NEXUS_PASS"'
          sh './gradlew publish'
        }
      }
    }
  }
}

pipeline {
  agent {
    docker {
      image 'ghcr.io/example/build-env@sha256:9c1f0a7e5b3d2c4f6a8e0b1d3c5e7f9a2b4c6d8e0f1a3b5c7d9e1f2a4b6c8d0e'
      args '--privileged'
    }
  }
  stages {
    stage('Build') {
      steps { sh 'make build' }
    }
  }
}

pipeline {
  agent {
    docker {
      image 'ghcr.io/example/ci-tools@sha256:3e5a7c9b1d2f4e6a8c0b2d4f6e8a1c3b5d7f9e0a2c4b6d8f1e3a5c7b9d0f2e4a'
      args '-v /var/run/docker.sock:/var/run/docker.sock'
    }
  }
  stages {
    stage('Image') {
      steps { sh 'docker build -t api:${GIT_COMMIT} .' }
    }
  }
}

pipeline {
  agent { label 'linux' }
  stages {
    stage('Fetch') {
      steps {
        copyArtifacts(projectName: 'build-api', selector: lastSuccessful(), filter: 'target/app.war')
      }
    }
    stage('Deploy') {
      when { branch 'main' }
      steps {
        sshagent(['tomcat-deploy']) {
          sh 'scp target/app.war deploy@app.example.com:/opt/tomcat/webapps/'
        }
      }
    }
  }
}

pipeline {
  agent { label 'linux' }
  stages {
    stage('Validate manifests') {
      steps {
        sh 'curl -fsSLO https://dl.example.com/tools/kubeval-0.16.1-linux-amd64.tgz'
        sh 'tar xzf kubeval-0.16.1-linux-amd64.tgz'
        sh './kubeval --strict k8s/*.yaml'
      }
    }
  }
}

pipeline {
  agent {
    docker { image 'eclipse-temurin@sha256:7d4e1f0a2b3c5d6e8f9a0b1c2d3e4f5a6b7c8d9e0f1a2b3c4d5e6f7a8b9c0d1e' }
  }
  environment {
    SONAR_TOKEN = credentials('sonar-token')
  }
  stages {
    stage('Analyze') {
      steps {
        sh './gradlew build sonar -Dsonar.host.url=https://sonar.example.com'
      }
    }
  }
}

pipeline {
  agent { label 'linux' }
  stages {
    stage('Fetch release') {
      steps {
        sh 'curl -fsSLO https://releases.example.com/app/3.2.0/app-3.2.0.tar.gz'
        sh 'curl -fsSLO https://releases.example.com/app/3.2.0/app-3.2.0.tar.gz.asc'
        sh 'gpg --no-default-keyring --keyring ./release-keys.gpg --verify app-3.2.0.tar.gz.asc app-3.2.0.tar.gz'
        sh 'tar xzf app-3.2.0.tar.gz'
      }
    }
  }
}
